// IR antes de optimizar
pipeline credit_risk (raíz) {
  %clients  = SOURCE { SQLITE(file: "bank.db", table: "clients") : TABLE }
  %cleaned  = FILL_NULL(%clients) { debt = 0 }
  %valid    = FILTER(%cleaned) { ((income IS NOT NULL) AND (income > 0)) AND (debt >= 0) }
  %enriched = DERIVE(%valid) { debt_ratio = SAFE_DIVIDE(debt, income); segment_label = COALESCE(segment, "UNKNOWN") }
  %flagged  = DERIVE(%enriched) { risk_flag = debt_ratio IS NULL }
  %summary  = AGGREGATE(%flagged) { GROUP_BY segment_label; COUNT() AS total_clients; COUNT(debt_ratio) AS ratios_available; AVG(debt_ratio) AS avg_debt_ratio }
  %output   = SINK(%summary) { PARQUET(file: "summary.parquet") }
}
pipeline clean_orders {
  %orders     = INPUT { TABLE[id: INT, customer_id: INT, amount: DECIMAL?, status: STRING?] }
  %non_null   = DROP_NULLS(%orders) { id, customer_id }
  %normalized = FILL_NULL(%non_null) { status = "UNKNOWN"; amount = 0 }
  %cleaned    = OUTPUT(%normalized) { TABLE[id: INT, customer_id: INT, amount: DECIMAL, status: STRING] }
}
pipeline order_report (raíz) {
