  %joined        = JOIN(left=%clean.cleaned, right=%customer_keys) { LEFT ON left.customer_id == right.customer_key }
  %selected      = SELECT(%joined) { customer_id, amount, status }
  %output        = SINK(%selected) { CSV(file: "orders_clean.csv") }
